/**
 * The showcase fixtures are generated by prepare-fixtures.py into node_modules/.cache/gallery and are not in the repository.
 * On a machine that has not generated them the type check still runs: these declarations stand in for the missing files.
 * When the files exist, TypeScript resolves the real JSON and these are not used.
 */
declare module '*/.cache/gallery/document.json' {
  const value: unknown;
  export default value;
}

declare module '*/.cache/gallery/model.json' {
  const value: unknown;
  export default value;
}

declare module '*/.cache/gallery/scene.json' {
  const value: unknown;
  export default value;
}

declare module '*/.cache/gallery/updated-model.json' {
  const value: unknown;
  export default value;
}
